# Demo4 analysis: bg cell -> 2 iff bounded in row or col by same-colored cells on both sides (nearest neighbors equal).
def f(g):
    g=[list(r) for r in g]
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    res=[[g[i][j] if g[i][j]!=bg else 2 for j in range(W)] for i in range(H)]
    def nearest(line,j):
        l=r=None
        n=len(line)
        for k in range(j-1,-1,-1):
            l=line[k]; break
        for k in range(j+1,n):
            r=line[k]; break
        return l,r
    for i in range(H):
        for j in range(W):
            if g[i][j]==bg:
                rl,rr=nearest(g[i],j)
                cu,cd=nearest([g[k][j] for k in range(H)],i)
                if (rl is not None and rr is not None and rl==rr and rl!=bg) or \
                   (cu is not None and cd is not None and cu==cd and cu!=bg):
                    res[i][j]=2
    return res

